def get_neighbors(r, c, n):
    neighbors = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            neighbors.append((nr, nc))
    return neighbors

def count_good_paths(n, board):
    # board is a 2D list
    local_minima = []
    for r in range(n):
        for c in range(n):
            is_min = True
            for nr, nc in get_neighbors(r, c, n):
                if board[nr][nc] < board[r][c]:
                    is_min = False
                    break
            if is_min:
                local_minima.append((r, c))

    total_paths = 0
    for start_r, start_c in local_minima:
        # count increasing paths starting from (start_r, start_c)
        # use DFS
        stack = [(start_r, start_c)]
        # wait, we need to count all paths, not just one
        # A path is (f1, f2, ..., fk)
        # we can use recursion with memoization? No, because it's a path, 
        # but it's an increasing path, so we can't revisit a node.

        def count_from(r, c):
            count = 1 # the path (r,c) itself
            for nr, nc in get_neighbors(r, c, n):
                if board[nr][nc] > board[r][c]:
                    count += count_from(nr, nc)
            return count

        total_paths += count_from(start_r, start_c)

    return total_paths

